"""The generated reference pages under ``docs/reference/``.

Each page is built entirely from facts and carries a header saying so. Prose
links to these pages for large tables instead of inlining them. A link to a
reference entry does not make a fact "covered" (C3): the page lists every fact.
"""

from __future__ import annotations

from collections.abc import Callable, Mapping

from .facts import Bindable, View, code

HEADER = (
    "<!-- Generated by `python scripts/docs_facts.py generate` from pyeye's code. "
    "Do not edit: change the code and regenerate. -->"
)

Facts = Mapping[str, Bindable]


def _page(title: str, intro: str, sections: list[tuple[str, str]]) -> str:
    parts = [HEADER, f"# {title}", intro]
    for heading, body in sections:
        parts.append(f"## {heading}")
        parts.append(body)
    return "\n\n".join(parts) + "\n"


def _tool_sections(facts: Facts, view_id: str) -> list[tuple[str, str]]:
    group = facts[view_id]
    if not isinstance(group, View):
        raise TypeError(f"{view_id!r} is a fact, not a view")
    sections = []
    for tool_id in group.members:
        name = tool_id.split(".", 1)[1]
        sections.append((code(name), facts[f"{tool_id}.params"].markdown))
    return sections


def tools_page(facts: Facts) -> str:
    """Every MCP tool and its parameters."""
    plugin_views = sorted(i for i in facts if i.startswith("tools.plugin."))
    parts = [
        HEADER,
        "# MCP tools",
        "Every tool pyeye registers, with its parameters, types and defaults, "
        "read from the live registration.",
        "## Core tools",
        facts["tools.core"].markdown,
        *[f"### {h}\n\n{b}" for h, b in _tool_sections(facts, "tools.core")],
        "## Admin tools",
        "Registered only when `PYEYE_ENABLE_PERFORMANCE_METRICS` is set.",
        facts["tools.admin"].markdown,
        *[f"### {h}\n\n{b}" for h, b in _tool_sections(facts, "tools.admin")],
        "## Plugin tools",
        "Registered when the plugin's framework is detected in the project.",
    ]
    for view_id in plugin_views:
        parts.append(f"### {view_id.rsplit('.', 1)[1].capitalize()}")
        parts.append(facts[view_id].markdown)
        parts.extend(f"#### {h}\n\n{b}" for h, b in _tool_sections(facts, view_id))
    return "\n\n".join(parts) + "\n"


def edges_page(facts: Facts) -> str:
    """Every edge, its kinds, ceiling and determinism tier, and what each means."""
    return _page(
        "Edges",
        "The edges `expand` and `trace` follow, from the edge registry.",
        [
            ("Implemented edges", facts["edges.table"].markdown),
            (
                "Deferred edges",
                "Reference edges, deferred until an indexed reference backend lands "
                '(`expand` answers them with `reason: "deferred_reference_backend"`): '
                + facts["edges.deferred"].markdown
                + ".",
            ),
            ("Ceilings", facts["ceilings.table"].markdown),
            ("Determinism", facts["determinism.table"].markdown),
        ],
    )


def env_page(facts: Facts) -> str:
    """Every ``PYEYE_*`` environment variable."""
    return _page(
        "Environment variables",
        "Every `PYEYE_*` variable pyeye reads, with its default and range. "
        "`unused` means loaded but read by nothing; `deprecated` variables are "
        "parsed and have no effect.",
        [("Variables", facts["env.all"].markdown)],
    )


def cli_page(facts: Facts) -> str:
    """The commands that start pyeye."""
    return _page(
        "Commands",
        "The supported ways to start the pyeye server.",
        [("Entry points", facts["cli.all"].markdown)],
    )


def index_page(facts: Facts) -> str:  # noqa: ARG001 - same signature as the others
    """The reference index."""
    links = "\n".join(
        f"- [{title}]({name})"
        for name, title in (
            ("tools.md", "MCP tools"),
            ("edges.md", "Edges"),
            ("env-vars.md", "Environment variables"),
            ("cli.md", "Commands"),
        )
    )
    return _page(
        "Reference",
        "Generated from the code, so it can't drift from it. Explanations live in the "
        "prose docs, which link here.",
        [("Pages", links)],
    )


#: Page path -> builder: the one list of generated pages (``docs.REFERENCE_PAGES``
#: registers exactly these).
PAGES: dict[str, Callable[[Facts], str]] = {
    "docs/reference/README.md": index_page,
    "docs/reference/tools.md": tools_page,
    "docs/reference/edges.md": edges_page,
    "docs/reference/env-vars.md": env_page,
    "docs/reference/cli.md": cli_page,
}
